//! The synthetic-request matrix: what the device does with every `eth-sign-request`
//! shape that no wallet will produce for us.
//!
//! The URs below are generated by `tools/ur-inject/gen.mjs --kind <k>` (BC-UR frames
//! a computer screen can show, so the device camera is the only transport needed).
//! Pinning them here makes the plan executable: the byte strings are stable, so a
//! change in dispatch, review or the reject codes turns this file red instead of
//! needing another round of hardware testing.
//!
//! What each row is for:
//! - `1559` / `personal` — the two shapes the device signs; the review text and the
//!   `v` domain are asserted (yParity vs 27/28).
//! - `712` — typed data, refused until it has a fixed-size container; the review must
//!   still report the payload size.
//! - `legacy`, `2930`, `4844`, `7702` — valid Ethereum schemes this signer does not
//!   implement: they must be refused as *unimplemented*, not as malformed.
//! - `unknown` — an unassigned type byte: malformed, refused with the format code.
//! - `presigned` — a payload that already carries a signature: not a signing request.
//! - `badchain` — the request says chain 5, the transaction says chain 1.
#![cfg(feature = "alloc-fallback")]

extern crate alloc;

use shlosilo::business::review;
use shlosilo::business::sign::{sign, SignInput};
use shlosilo::error::ShlosiloErrorKind;
use shlosilo::ur::codec::eth_signature::parse_eth_signature;
use shlosilo::ur::ur_decode;
use shlosilo::ur::ur_encode::UrTypeTag;

enum Expect {
    /// Signs; the review renders these substrings, and `v` is checked per scheme.
    Sign {
        review_has: &'static [&'static str],
        v_domain: VDomain,
    },
    /// Review renders an explanation (it is honest about what the payload is) but the
    /// sign path refuses with this kind — typed data is explained, not signed.
    ReviewOnly {
        review_has: &'static [&'static str],
        refuse: ShlosiloErrorKind,
    },
    /// Review refuses with this kind (and signing refuses the same way).
    Refuse(ShlosiloErrorKind),
}

#[derive(Clone, Copy, PartialEq)]
enum VDomain {
    /// EIP-1559: the bare yParity byte.
    YParity,
    /// EIP-191: 27 / 28.
    Eip191,
}

struct Case {
    kind: &'static str,
    ur: &'static str,
    expect: Expect,
}

