fn payload(ur: &str) -> alloc::vec::Vec<u8> {
    let decoded = ur_decode::decode(ur).expect("ur decodes");
    assert_eq!(decoded.type_tag(), UrTypeTag::EthSignRequest);
    decoded.as_ref().to_vec()
}

fn review_text(view: &review::ReviewView) -> alloc::string::String {
    let mut s = alloc::string::String::new();
    for l in view.lines() {
        s.push_str(l.as_str());
        s.push('\n');
    }
    s
}

#[test]
fn the_matrix_matches_the_device_behaviour() {
    let seed = [7u8; 64];
    for case in CASES {
        let payload = payload(case.ur);
        match case.expect {
            Expect::Sign {
                review_has,
                v_domain,
            } => {
                let view = review::build_eth(&payload)
                    .unwrap_or_else(|_| panic!("{}: review must render", case.kind));
                let text = review_text(&view);
                for needle in review_has {
                    assert!(
                        text.contains(needle),
                        "{}: review must contain {needle:?}; got:\n{text}",
                        case.kind
                    );
                }

                let mut out = [0u8; 512];
                let n = sign(
                    SignInput::Seed { seed: &seed },
                    UrTypeTag::EthSignRequest,
                    &payload,
                    &mut out,
                )
                .unwrap_or_else(|e| panic!("{}: must sign, got {:?}", case.kind, e.kind));
                let sig = parse_eth_signature(&out[..n])
                    .unwrap_or_else(|_| panic!("{}: exit must be a container", case.kind));
                let v = sig.signature[64];
                match v_domain {
                    VDomain::YParity => assert!(
                        v <= 1,
                        "{}: EIP-1559 carries the bare yParity, got v={v}",
                        case.kind
                    ),
                    VDomain::Eip191 => assert!(
                        v == 27 || v == 28,
                        "{}: EIP-191 carries v = 27/28, got v={v}",
                        case.kind
                    ),
                }
            }
            Expect::ReviewOnly { review_has, refuse } => {
                let view = review::build_eth(&payload)
                    .unwrap_or_else(|_| panic!("{}: review must explain", case.kind));
                let text = review_text(&view);
                for needle in review_has {
                    assert!(
                        text.contains(needle),
                        "{}: review must contain {needle:?}; got:\n{text}",
                        case.kind
                    );
                }
                let mut out = [0u8; 512];
                match sign(
                    SignInput::Seed { seed: &seed },
                    UrTypeTag::EthSignRequest,
                    &payload,
                    &mut out,
                ) {
                    Ok(_) => panic!("{}: must not sign", case.kind),
                    Err(e) => assert_eq!(e.kind, refuse, "{}: sign code", case.kind),
                }
            }
            Expect::Refuse(kind) => {
                match review::build_eth(&payload) {
                    Ok(view) => panic!(
                        "{}: review must refuse, but rendered:\n{}",
                        case.kind,
                        review_text(&view)
                    ),
                    Err(e) => assert_eq!(e.kind, kind, "{}: review code", case.kind),
                }
                let mut out = [0u8; 512];
                match sign(
                    SignInput::Seed { seed: &seed },
                    UrTypeTag::EthSignRequest,
                    &payload,
                    &mut out,
                ) {
                    Ok(_) => panic!("{}: must not sign", case.kind),
                    Err(e) => assert_eq!(e.kind, kind, "{}: sign code", case.kind),
                }
            }
        }
    }
}

/// An `approve` signature is only useful if it verifies. This recovers the signer of
/// both approve payloads (finite and unlimited) with the plain EIP-1559 digest and
/// compares it with the public key derived from the same seed/path the exit used — so
/// "the device approved a spender" is checked with the same arithmetic a node would
/// apply, without broadcasting anything.
#[test]
fn approve_signatures_recover_to_the_device_address() {
    use shlosilo::address::eth as eth_address;
    use shlosilo::chain::eth::{eip1559, from_rlp, sign as eth_sign};
    use shlosilo::curve_primitive::secp256k1;
    use shlosilo::derivation::bip32_secp256k1::derive_from_seed;
    use shlosilo::derivation::path::DerivationPath;
    use shlosilo::encoding::keccak256;
    use shlosilo::ur::codec::eth_sign_request::parse_eth_sign_request;

    let seed = [7u8; 64];
    let path = DerivationPath::parse("m/44'/60'/0'/0/0").unwrap();
    let sk = derive_from_seed(&seed, &path).unwrap();
    let device_pub = secp256k1::point_to_uncompressed(&secp256k1::base_mul(&sk));

    for kind in ["approve", "approve-unlimited"] {
        let case = CASES
            .iter()
            .find(|c| c.kind == kind)
            .expect("approve case present");
        let payload = payload(case.ur);
        let req = parse_eth_sign_request(&payload).expect("request parses");
        let tx = from_rlp::parse_eip1559_signing_request(req.sign_data).expect("tx parses");
        let sighash = eip1559::signing_hash(&tx).expect("sighash");

        let mut out = [0u8; 512];
        let n = sign(
            SignInput::Seed { seed: &seed },
            UrTypeTag::EthSignRequest,
            &payload,
            &mut out,
        )
        .expect("signs");
        let sig = parse_eth_signature(&out[..n]).expect("container");

        // The container carries the bare yParity; recovery takes the EIP-191-style
        // 27/28 form, so the offset is applied here (never on the wire).
        let mut sig65 = sig.signature;
        sig65[64] += 27;
        let recovered = eth_sign::ecdsa_recover(&sighash, &sig65).expect("recover");
        assert_eq!(
            recovered,
            device_pub[1..],
            "{kind}: the signature must verify against the device's own public key"
        );

        let h = keccak256::hash(&recovered).unwrap();
        let mut addr = [0u8; 20];
        addr.copy_from_slice(&h[12..]);
        let rendered = eth_address::encode_bytes(&addr).unwrap();
        assert_eq!(
            rendered.as_ref().len(),
            42,
            "{kind}: address renders as an EIP-55 string"
        );
    }
}
